<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Platform audit · eRPH Pro</title><style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:14px system-ui,sans-serif}.top{height:70px;padding:0 28px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line)}.top a{color:var(--muted);text-decoration:none}.main{max-width:1180px;margin:auto;padding:38px 22px}.title{font-size:32px;letter-spacing:-.04em}.muted{color:var(--muted)}.card{overflow:auto;margin-top:20px;padding:12px;border:1px solid var(--line);border-radius:15px;background:#fff}table{width:100%;min-width:760px;border-collapse:collapse}th,td{text-align:left;padding:13px;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}td{font-size:13px}.context{display:block;color:var(--muted);font-size:11px;margin-top:4px;white-space:pre-wrap}</style></head><body><header class="top"><strong>eRPH Pro · Platform audit</strong><a href="{{ route('owner.dashboard') }}">Back to owner overview</a></header><main class="main"><h1 class="title">Audit activity</h1><p class="muted">Read-only cross-school activity. Sensitive support access must still be separately granted and time-limited.</p><section class="card"><table><thead><tr><th>Time</th><th>School</th><th>Actor</th><th>Action</th><th>Context</th></tr></thead><tbody>@forelse($logs as $log)<tr><td>{{ $log->created_at }}</td><td>{{ $log->school_name ?: 'Platform' }}</td><td>{{ $log->actor_name ?: 'System' }}</td><td>{{ $log->action }}</td><td><span class="context">{{ $log->context ?: '—' }}</span></td></tr>@empty<tr><td colspan="5">No audit activity recorded.</td></tr>@endforelse</tbody></table></section></main></body></html>
